const WHY='Why Have Rules', MEET='What Happens at a Meeting?', MOT='Handling Motions', DEB='Debate', AMD='Amendments', POST='Postponing and Referring to a Committee', MIND='How a Group Can Change Its Mind', VOTE='Voting and Elections', BYL='Bylaws and Other Rules and How to Use Them', ENF='How Rules are Enforced and Suspended', TABLE='Table of Rules', OFF='Officers, Committee Chairman, or Member';

